import { FC, HTMLAttributes, ReactNode } from 'react';

import { Flex, Typography } from 'antd';

import { useMedia } from 'shared/hooks';

interface IPageTitleProps extends HTMLAttributes<HTMLDivElement> {
	component?: ReactNode;
	inlineComponent?: ReactNode;
	subtitle?: ReactNode;
	subtitleMaxWidth?: number;
}

export const PageTitle: FC<IPageTitleProps> = ({
	className,
	children,
	component,
	inlineComponent,
	subtitle,
	subtitleMaxWidth = 720,
	...props
}) => {
	const isMd = useMedia();

	return (
		<Flex vertical gap={12} align={isMd ? 'start' : 'stretch'}>
			<Flex
				{...props}
				justify={inlineComponent ? 'start' : 'space-between'}
				align="center"
				gap={12}
				className={className}
				style={{ width: '100%' }}>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{children}
				</Typography.Title>
				{inlineComponent}
				{!isMd && component}
			</Flex>
			{subtitle && (
				<Typography.Text type="secondary" style={{ maxWidth: subtitleMaxWidth }}>
					{subtitle}
				</Typography.Text>
			)}
			{isMd && component}
		</Flex>
	);
};
